<map version="1.0.1"><node TEXT="AIGC课程菜单｜47门·75小时"><node TEXT="通用基础" COLOR="#225cc5"><node TEXT="F01 AIGC视频入门：一条片子的生产地图（1h）" COLOR="#225cc5"><node TEXT="面向第一次接触AI视频的学员，用一条商家短片追踪从需求到交付的全过程，建立任务、文件和人员之间的关系。" /><node TEXT="成果：一张个人视频生产流程图" /><node TEXT="前置：—" /><node TEXT="成片逆向拆解 · 10分钟"><node TEXT="区分文案、图像、视频、声音与包装" /><node TEXT="找到每种素材的来源" /></node><node TEXT="生产流程示范 · 15分钟"><node TEXT="串联任务书、脚本、分镜、资产、生成、剪辑和审核" /><node TEXT="明确每一步交接物" /></node><node TEXT="绘制生产地图 · 25分钟"><node TEXT="为一条15秒产品片安排步骤" /><node TEXT="标出可复用素材与人工判断点" /></node><node TEXT="地图讲评 · 10分钟"><node TEXT="检查漏项与先后关系" /><node TEXT="用失败案例说明返工如何向上游追溯" /></node></node><node TEXT="F02 把需求讲清楚：从客户想法到创作任务书（1h）" COLOR="#225cc5"><node TEXT="以“帮我做一条好看的宣传片”为起点，把模糊委托改写成可以报价、制作和验收的任务书。" /><node TEXT="成果：一页创作任务书与验收要点" /><node TEXT="前置：—" /><node TEXT="需求访谈 · 10分钟"><node TEXT="追问受众、渠道和观看后行动" /><node TEXT="区分客户愿望与必要信息" /></node><node TEXT="任务书示范 · 15分钟"><node TEXT="填写时长、比例、核心信息和品牌限制" /><node TEXT="列出客户应提供的素材" /></node><node TEXT="模拟客户沟通 · 25分钟"><node TEXT="将模糊需求改写成一页任务书" /><node TEXT="写明不确定事项与确认节点" /></node><node TEXT="验收校对 · 10分钟"><node TEXT="用任务书检查一条候选片" /><node TEXT="把“高级一点”改成可观察的修改要求" /></node></node><node TEXT="F03 选题与开头：让观众愿意继续看（1h）" COLOR="#225cc5"><node TEXT="围绕目标观众的真实问题设计选题，把“吸引人”落实为可验证的开头方案，避免把传播效果当作承诺。" /><node TEXT="成果：3个选题、3版开头与选择理由" /><node TEXT="前置：—" /><node TEXT="观众与场景 · 10分钟"><node TEXT="确定谁在何时观看" /><node TEXT="区分兴趣点、痛点与信息价值" /></node><node TEXT="开头拆解 · 15分钟"><node TEXT="比较结果前置、问题引入和反差开场" /><node TEXT="检查标题与内容是否一致" /></node><node TEXT="选题练习 · 25分钟"><node TEXT="为一个服务写三种选题与两个开头" /><node TEXT="标注画面、台词和兑现内容" /></node><node TEXT="方案评议 · 10分钟"><node TEXT="检查信息是否具体且可兑现" /><node TEXT="确定一项后续观察指标" /></node></node><node TEXT="F04 脚本小课：把一个卖点写成30秒故事（1h）" COLOR="#225cc5"><node TEXT="以一个产品或服务卖点为材料，在30秒内安排人物、问题、变化和行动，让文案能被拍成镜头。" /><node TEXT="成果：一份30秒脚本及压缩版" /><node TEXT="前置：—" /><node TEXT="卖点取舍 · 10分钟"><node TEXT="从功能表中选择一个利益点" /><node TEXT="明确观众相信它需要什么证据" /></node><node TEXT="结构示范 · 15分钟"><node TEXT="安排情境、阻碍、变化与行动" /><node TEXT="区分画面表达和旁白补充" /></node><node TEXT="脚本写作 · 25分钟"><node TEXT="完成分段画面与台词" /><node TEXT="朗读计时并删除重复信息" /></node><node TEXT="脚本讲评 · 10分钟"><node TEXT="核对卖点依据和前后因果" /><node TEXT="将无法拍摄的抽象句改写成动作" /></node></node><node TEXT="F05 分镜小课：把文字变成镜头清单（1h）" COLOR="#225cc5"><node TEXT="把一段脚本拆成镜头清单，学会用景别、视线、时长和切点组织信息，为画布和导演台提供明确输入。" /><node TEXT="成果：一份4—6镜分镜表" /><node TEXT="前置：—" /><node TEXT="镜头任务 · 10分钟"><node TEXT="区分交代环境、呈现动作和强调细节" /><node TEXT="判断何时需要切镜" /></node><node TEXT="分镜示范 · 15分钟"><node TEXT="填写景别、机位、人物动作、声音和时长" /><node TEXT="检查轴线与视线方向" /></node><node TEXT="分镜练习 · 25分钟"><node TEXT="把30秒脚本拆成4—6镜" /><node TEXT="绘制首尾构图并标出转场依据" /></node><node TEXT="连贯性检核 · 10分钟"><node TEXT="用分镜口述故事" /><node TEXT="发现信息重复和缺失并调整顺序" /></node></node><node TEXT="F06 提示词小课：从碰运气到可控修改（1h）" COLOR="#225cc5"><node TEXT="建立简洁、可迭代的提示词结构，学会区分必须保持的条件与允许变化的内容，形成可复用的修改记录。" /><node TEXT="成果：一组提示词与修改对照记录" /><node TEXT="前置：—" /><node TEXT="提示词诊断 · 10分钟"><node TEXT="识别空泛形容、冲突要求和过量动作" /><node TEXT="区分图像提示与视频提示" /></node><node TEXT="结构示范 · 15分钟"><node TEXT="组织主体、场景、动作、镜头与限制" /><node TEXT="说明参考图与文本的分工" /></node><node TEXT="对照练习 · 25分钟"><node TEXT="针对同一素材只改变一个变量" /><node TEXT="保存输入、结果和版本备注" /></node><node TEXT="结果归因 · 10分钟"><node TEXT="比较预期与实际差异" /><node TEXT="决定保留、重写或降低任务复杂度" /></node></node><node TEXT="F07 角色与产品一致性：建立可复用资产包（1h）" COLOR="#225cc5"><node TEXT="针对角色换脸、商品变形与服装漂移建立资产基准，学习用参照与检查表降低跨镜头返工。" /><node TEXT="成果：角色／产品卡及3张一致性候选图" /><node TEXT="前置：—" /><node TEXT="漂移识别 · 10分钟"><node TEXT="对照人物与商品失败样例" /><node TEXT="区分身份、服装、结构与色彩变化" /></node><node TEXT="资产包示范 · 15分钟"><node TEXT="建立角色正侧面与产品细节参照" /><node TEXT="统一命名、来源和固定描述" /></node><node TEXT="资产整理 · 25分钟"><node TEXT="为原创角色或商品建立基准页" /><node TEXT="写出不可变清单与允许变化项" /></node><node TEXT="一致性验收 · 10分钟"><node TEXT="比较三个候选镜头" /><node TEXT="标记需要返修的具体区域" /></node></node><node TEXT="F08 关键帧设计：先定画面，再生成运动（1h）" COLOR="#225cc5"><node TEXT="在生成视频之前先确定关键构图，用首帧与目标尾帧约束信息表达，减少先生成再猜测的成本。" /><node TEXT="成果：一组首尾画面与动作说明" /><node TEXT="前置：—" /><node TEXT="画面任务 · 10分钟"><node TEXT="分析首帧建立的信息与尾帧留下的问题" /><node TEXT="区分关键帧与普通参考图" /></node><node TEXT="构图示范 · 15分钟"><node TEXT="安排主体位置、留白、景深与动作空间" /><node TEXT="检查首尾的空间关系" /></node><node TEXT="关键帧练习 · 25分钟"><node TEXT="制作同一镜头的起始构图和目标结束构图" /><node TEXT="写出中间动作路径" /></node><node TEXT="可行性讲评 · 10分钟"><node TEXT="排查视角突变、遮挡和形态变化" /><node TEXT="过大变化拆成多个镜头" /></node></node><node TEXT="F09 视频生成诊断：镜头为什么失败（1h）" COLOR="#225cc5"><node TEXT="围绕一个失败镜头建立诊断顺序，在改素材、改提示、缩短镜头和重拍之间作选择。" /><node TEXT="成果：一个镜头的修复前后对照" /><node TEXT="前置：—" /><node TEXT="缺陷分类 · 10分钟"><node TEXT="区分身份漂移、动作断裂、镜头失控和物理失真" /><node TEXT="记录发生时点" /></node><node TEXT="排查示范 · 15分钟"><node TEXT="依次核对输入素材、动作数量、遮挡和时长" /><node TEXT="避免一次改动全部设置" /></node><node TEXT="修订实验 · 25分钟"><node TEXT="为一段失败片提出两条修复路径" /><node TEXT="实际测试一项并保留前后对照" /></node><node TEXT="成本复盘 · 10分钟"><node TEXT="比较质量、耗时与重试次数" /><node TEXT="说明继续生成或改用剪辑的理由" /></node></node><node TEXT="F10 配音与声音：让画面有节奏和情绪（1h）" COLOR="#225cc5"><node TEXT="为短片安排人声、音乐和环境声，让音轨承担信息与节奏；通过听辨和响度检查发现常见问题。" /><node TEXT="成果：一段20—30秒声音设计练习" /><node TEXT="前置：—" /><node TEXT="声音拆解 · 10分钟"><node TEXT="识别人声、环境、音效与音乐的作用" /><node TEXT="标出声音与画面的信息重复" /></node><node TEXT="配音示范 · 15分钟"><node TEXT="标注停连、重音与情绪" /><node TEXT="检查专有名词和数字读音" /></node><node TEXT="声音练习 · 25分钟"><node TEXT="为短片配置三层音轨" /><node TEXT="调整人声优先关系与入出点" /></node><node TEXT="听审讲评 · 10分钟"><node TEXT="用耳机和扬声器检查失真、遮蔽与突兀切断" /><node TEXT="核对音乐来源" /></node></node><node TEXT="F11 剪辑与包装：把镜头组装成片（1h）" COLOR="#225cc5"><node TEXT="把分散的生成镜头剪成有信息顺序的短片，重点练习节奏、字幕、声音和导出检查。" /><node TEXT="成果：一条15—30秒练习成片" /><node TEXT="前置：—" /><node TEXT="粗剪结构 · 10分钟"><node TEXT="按任务书排列镜头" /><node TEXT="删去重复信息与无效等待" /></node><node TEXT="包装示范 · 15分钟"><node TEXT="设置字幕层级、品牌落版和安全区域" /><node TEXT="保持声音连续" /></node><node TEXT="剪辑练习 · 25分钟"><node TEXT="完成一次粗剪到精剪" /><node TEXT="统一镜头比例并处理明显跳切" /></node><node TEXT="导出复查 · 10分钟"><node TEXT="核对清晰度、比例、字幕错字和黑帧" /><node TEXT="完整播放最终文件" /></node></node><node TEXT="F12 成片审核：质量、授权与AI标识（1h）" COLOR="#225cc5"><node TEXT="建立发布前的检查流程，区分画面质量、事实准确、素材权限和平台标识要求，形成可交接的审核记录。" /><node TEXT="成果：作品自查表与素材来源表" /><node TEXT="前置：—" /><node TEXT="审核分层 · 10分钟"><node TEXT="区分技术质量、内容事实、肖像声音与版权材料" /><node TEXT="确定审核负责人" /></node><node TEXT="案例核对 · 15分钟"><node TEXT="追踪图片、音乐、角色和商标的来源记录" /><node TEXT="查找拟发布平台的当前标识入口" /></node><node TEXT="审核练习 · 25分钟"><node TEXT="逐项检查课堂样片" /><node TEXT="将缺陷标为修订、待核实或可交付" /></node><node TEXT="交接复核 · 10分钟"><node TEXT="整理授权记录、版本与生成说明" /><node TEXT="对待确认事项设置阻断点" /></node></node><node TEXT="F13 镜头调度：把视频提示词写成拍摄施工单（1h）" COLOR="#225cc5"><node TEXT="以一个五秒镜头为单位，把“画面好看但动作失控”转化为可执行的拍摄设计。课程串联人物表演、摄影机路径、环境反馈与最终构图，训练从导演意图到视频提示词的表达。" /><node TEXT="成果：镜头施工单＋5秒测试或候选片分析＋变量对照表" /><node TEXT="前置：无硬性前置，建议先学F05、F06、F08" /><node TEXT="镜头蓝图与任务 · 10分钟"><node TEXT="回答主体、初态、动作、机位路径、环境反应、尾帧六问" /><node TEXT="把情绪改写为眼神、手部和呼吸" /></node><node TEXT="表演与空间示范 · 15分钟"><node TEXT="拆解准备、发力、余势及触发—反应顺序" /><node TEXT="用景别、机位高度、路径终点和前中后景约束镜头" /></node><node TEXT="五秒镜头实验 · 25分钟"><node TEXT="填写镜头施工单并组织角色、光线、材质与物理反馈" /><node TEXT="固定素材逐次验证2—3个变量并记录实际结果" /></node><node TEXT="结果评议与拆镜 · 10分钟"><node TEXT="检查动作因果、角色身份和尾帧落点" /><node TEXT="多人表演或复杂转场失控时拆镜并在剪辑中完成" /></node></node></node><node TEXT="工具入门" COLOR="#7040b4"><node TEXT="T01 画布工具上手：做出第一条产品短片（2h）" COLOR="#7040b4"><node TEXT="用统一练习素材在画布中组织文案、图像与视频任务，走通一次能保存、修改和导出的短片制作流程。" /><node TEXT="成果：一条10—15秒、2—3镜产品练习片" /><node TEXT="前置：—" /><node TEXT="任务与环境 · 15分钟"><node TEXT="核对账号额度和案例素材" /><node TEXT="阅读10—15秒产品片任务" /></node><node TEXT="操作示范 · 20分钟"><node TEXT="创建画布并组织素材与生成步骤" /><node TEXT="演示修改、版本留存及结果选择" /></node><node TEXT="镜头生产 · 45分钟"><node TEXT="制作2—3个候选镜头" /><node TEXT="至少修改一个画面问题并保存对照" /></node><node TEXT="组装与导出 · 25分钟"><node TEXT="在工具支持范围内整理素材并配套剪辑" /><node TEXT="导出后检查比例、声音与字幕" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成一条10—15秒产品短片与工程记录" /><node TEXT="按以下标准自评与互评：任务链可复现；至少一次有效修改；文件可播放" /></node></node><node TEXT="T02 转绘工具上手：拆解并重做一段视频（2h）" COLOR="#7040b4"><node TEXT="用一段授权短视频完成拆镜、设定风格、转绘和回看，建立“保留什么、改变什么”的基础操作习惯。" /><node TEXT="成果：一段5—10秒转绘样片及拆解表" /><node TEXT="前置：—" /><node TEXT="源片选择 · 15分钟"><node TEXT="检查人物、运动、遮挡与清晰度" /><node TEXT="标出5—10秒练习范围" /></node><node TEXT="操作示范 · 20分钟"><node TEXT="载入素材与风格参照" /><node TEXT="在实际版本可用选项内设置任务并记录输入" /></node><node TEXT="转绘试做 · 45分钟"><node TEXT="生成候选结果并与源片对照" /><node TEXT="针对角色或背景问题修改一次" /></node><node TEXT="对照与交付 · 25分钟"><node TEXT="核对动作、时序、画面稳定和声音保留情况" /><node TEXT="导出前后对照" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成5—10秒转绘样片和保留／改变清单" /><node TEXT="按以下标准自评与互评：变化目标明确；动作可识别；设置与结果可追溯" /></node></node><node TEXT="T03 导演台上手：从短剧本到剧情样片（2h）" COLOR="#7040b4"><node TEXT="以单场景短剧本为材料，认识导演台中剧本、角色、分镜与成片的关联，完成一次小规模端到端练习。" /><node TEXT="成果：一条20—30秒、单场景剧情练习片" /><node TEXT="前置：—" /><node TEXT="剧本准备 · 15分钟"><node TEXT="限定人物、地点和20—30秒剧情" /><node TEXT="确认素材与配套声音能力" /></node><node TEXT="流程示范 · 20分钟"><node TEXT="组织剧本、角色与场景资产" /><node TEXT="检查自动拆分结果并修订镜头任务" /></node><node TEXT="剧情生成 · 45分钟"><node TEXT="完成单场景关键镜头" /><node TEXT="保留人物描述和生成记录" /></node><node TEXT="成片整理 · 25分钟"><node TEXT="排列对白和镜头反应" /><node TEXT="检查人物关系、节奏与导出文件" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成20—30秒剧情样片与镜头清单" /><node TEXT="按以下标准自评与互评：剧本信息落地；角色可辨；故事能够理解" /></node></node></node><node TEXT="案例实战" COLOR="#086a56"><node TEXT="P01 TVC广告：做一条15秒品牌概念片（2h）" COLOR="#086a56"><node TEXT="围绕一个品牌利益点制作15秒概念广告，体验从创意提案到镜头选择和品牌落版的完整小项目。" /><node TEXT="成果：一条15秒TVC概念样片与创意说明" /><node TEXT="前置：T01" /><node TEXT="品牌简报 · 15分钟"><node TEXT="明确受众、承诺和证据" /><node TEXT="选择单一视觉概念" /></node><node TEXT="创意预演 · 20分钟"><node TEXT="写15秒结构与3—4镜分镜" /><node TEXT="建立产品和色彩基准" /></node><node TEXT="画布制作 · 45分钟"><node TEXT="生成主视觉及关键动态镜头" /><node TEXT="比较候选并修订产品或动作问题" /></node><node TEXT="广告精剪 · 25分钟"><node TEXT="安排节奏、声音和落版" /><node TEXT="检查品牌识别与文字准确" /></node><node TEXT="展示、评价与迁移 · 15分钟"><node TEXT="展示完成15秒品牌概念片和创意说明" /><node TEXT="按以下标准自评与互评：卖点可感知；产品识别稳定；落版清楚" /></node></node><node TEXT="P02 电商产品视频：让商品卖点可视化（2h）" COLOR="#086a56"><node TEXT="从真实商品资料提取一个使用价值，用场景与细节镜头呈现卖点，并保留可核对的商品信息。" /><node TEXT="成果：一条15—20秒产品展示样片" /><node TEXT="前置：T01" /><node TEXT="商品拆解 · 15分钟"><node TEXT="核实功能与外观资料" /><node TEXT="选择一